# 47_scandal_break_test.R
# Formal Chow break test on the financial-scandal rate series (Figure 3.5,
# Panel C), PJ 10 Sep: "can you do a breakpoint and statistical test for
# panel C".
#
# METHOD: IDENTICAL to 45_ministerial_departures_break_test.R's mean-shift
# Chow (df1=1) + permutation significance test (same as the professionalisation
# composite's break analysis) - reused verbatim for a like-for-like result
# across all three panels, not a new ad hoc method.
#
# ⚠ CAVEAT specific to this series, flagged up front: financial scandal is a
# RARE, ZERO-INFLATED count series (12 events across 47 years, 38 of them
# exactly 0) - a much rougher fit for a mean-shift F-test than the smoother
# Reshuffles/Standalone rates this same method was built for. The permutation
# step is still valid (it resamples the ACTUAL observed values, so it doesn't
# assume normality), but with this few non-zero points a single well-timed
# cluster of events can dominate the result - treat any "significant" break
# here as a description of when scandal events happened to cluster, not
# evidence of a structural shift in scandal risk.
#
# DATA: data/processed/scandal_resignations_annual_1979_2025.csv
# OUTPUT: console only - diagnostic, not yet a figure or appendix table.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
d <- read_csv(file.path(PROJECT, "data/processed/scandal_resignations_annual_1979_2025.csv"),
              show_col_types = FALSE) |> arrange(year)

set.seed(42)
NPERM <- 10000

.rss_mean <- function(y) { s <- sum((y - mean(y))^2); if (is.na(s)) 0 else s }
chow_F_meanshift <- function(y, k, min_seg = 3) {
  n <- length(y); if (k < min_seg || k > n - min_seg) return(NA_real_)
  rss_pool <- .rss_mean(y); rss_split <- .rss_mean(y[1:k]) + .rss_mean(y[(k + 1):n])
  if (rss_split <= 0) return(NA_real_)
  ((rss_pool - rss_split) / 1) / (rss_split / (n - 2))
}
.ks_interior <- function(n, trim = 0.15, min_seg = 3) {
  lo <- max(min_seg, floor(trim * n)); hi <- min(n - min_seg, n - floor(trim * n)); lo:hi
}
supF_meanshift <- function(y, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  f <- vapply(ks, function(k) chow_F_meanshift(y, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(f)]], peak_F = max(f, na.rm = TRUE),
       curve = data.frame(year = year[ks], F = f))
}
perm_pvalue <- function(y, year, observed_F, trim = 0.15, min_seg = 3, nperm = NPERM) {
  perm_max <- replicate(nperm, {
    ys <- sample(y)
    supF_meanshift(ys, year, trim, min_seg)$peak_F
  })
  mean(perm_max >= observed_F, na.rm = TRUE)
}

y <- d$scandal_rate_pct; yr <- d$year
cat(sprintf("N years = %d, non-zero years = %d, total events = %d\n",
            length(y), sum(y > 0), sum(d$n_scandal)))

res <- supF_meanshift(y, yr)
pval <- perm_pvalue(y, yr, res$peak_F)
cat(sprintf("\n=== scandal_rate_pct ===\n"))
cat(sprintf("Peak break year: %d, F = %.2f, permutation p = %.4f (%d draws)\n",
            res$peak_year, res$peak_F, pval, NPERM))
cat("Top 5 candidate years by F:\n")
print(res$curve |> arrange(desc(F)) |> head(5))

# Supplementary, given the caveat above: simple pre/post mean comparison at
# the peak break year, and a period-level summary, so the break result isn't
# read in isolation from the raw pattern.
k <- which(yr == res$peak_year)
cat(sprintf("\nMean rate before %d: %.3f%% (n=%d)\n", res$peak_year, mean(y[1:k]), k))
cat(sprintf("Mean rate from %d:  %.3f%% (n=%d)\n", res$peak_year, mean(y[(k+1):length(y)]), length(y)-k))
